"""Type-collision regression tests for the window proof bundle diff chain.

The value engine reuses a verified leaf credential when a later occurrence
is equal in both type and value.  These tests pin down that a credential
whose compact JSON text merely *looks* like an already-verified one — an
integer fact or condition key where the same digits were verified as a
string, or a tuple where the contract requires a list — can never reuse
the legal credential's result: both the diff generator and the diff
verifier must reject it with ``ValueError``.
"""

import pytest
from fastapi.testclient import TestClient

from regulation_policy_compiler.app import app
from regulation_policy_compiler.policy import (
    checkpoint_chain,
    checkpoint_chain_checkpoint,
    checkpoint_chain_checkpoint_bundle,
    checkpoint_chain_checkpoint_bundle_diff,
    decision_matrix_attestation,
    decision_matrix_attestation_bundle,
    evolution_checkpoint,
    evolution_checkpoint_bundle,
    matrix_bundle_evolution,
    verify_checkpoint_chain_checkpoint_bundle_diff,
)

client = TestClient(app)

START = "2021-01-01T00:00:00Z"
END = "2021-04-01T00:00:00Z"
AT1 = "2021-05-01T00:00:00Z"
AT2 = "2021-06-01T00:00:00Z"
RT1 = "2021-08-01T00:00:00Z"
RT2 = "2021-09-01T00:00:00Z"

GENERATE_PATH = (
    "/decision-matrix/attest/bundle/evolution/checkpoint/bundle/diff/"
    "chain/checkpoint/bundle/diff"
)
VERIFY_PATH = GENERATE_PATH + "/verify"


def _rule(**overrides):
    rule = {
        "id": "r1",
        "ver": 1,
        "source": "law",
        "priority": 0,
        "from": "2020-01-01T00:00:00Z",
        "to": None,
        "when": None,
        "result": "allow",
    }
    rule.update(overrides)
    return rule


def _report_a():
    # The fact and condition key is the string "1": an equal-text twin
    # carrying the integer key 1 serializes identically but is illegal.
    return decision_matrix_attestation(
        START,
        END,
        [{"id": "c1", "facts": {"1": True}}],
        [_rule(when={"1": True}, result="允许")],
    )


def _report_b():
    return decision_matrix_attestation(
        START, END, [{"id": "c2", "facts": {}}], [_rule(result="z")]
    )


def _chain():
    bundle_one = decision_matrix_attestation_bundle(
        [{"id": "a", "report": _report_a()}]
    )
    bundle_two = decision_matrix_attestation_bundle(
        [
            {"id": "a", "report": _report_a()},
            {"id": "b", "report": _report_b()},
        ]
    )
    evolution = matrix_bundle_evolution(
        [
            {"at": AT1, "bundle": bundle_one},
            {"at": AT2, "bundle": bundle_two},
        ]
    )
    proof_one = evolution_checkpoint(evolution, AT1, AT1)
    proof_two = evolution_checkpoint(evolution, AT1, AT2)
    return checkpoint_chain(
        [
            {
                "at": RT1,
                "bundle": evolution_checkpoint_bundle(
                    [{"id": "a", "proof": proof_one}]
                ),
            },
            {
                "at": RT2,
                "bundle": evolution_checkpoint_bundle(
                    [{"id": "a", "proof": proof_two}]
                ),
            },
        ]
    )


def _window_proof(start, end):
    return checkpoint_chain_checkpoint(_chain(), start, end)


def _bundle_before():
    return checkpoint_chain_checkpoint_bundle(
        [{"id": "alpha", "proof": _window_proof(RT1, RT1)}]
    )


def _bundle_after():
    return checkpoint_chain_checkpoint_bundle(
        [
            {"id": "alpha", "proof": _window_proof(RT1, RT1)},
            {"id": "beta", "proof": _window_proof(RT2, RT2)},
        ]
    )


def _diff():
    return checkpoint_chain_checkpoint_bundle_diff(_bundle_before(), _bundle_after())


def _expected(report):
    return {
        "before_root": report["before_root"],
        "after_root": report["after_root"],
        "before_ids": [member["id"] for member in report["before"]["proofs"]],
        "after_ids": [member["id"] for member in report["after"]["proofs"]],
        "digest": report["digest"],
    }


def _int_fact_key(node):
    if isinstance(node, dict):
        facts = node.get("facts")
        if isinstance(facts, dict) and "1" in facts:
            facts[1] = facts.pop("1")
        for value in node.values():
            _int_fact_key(value)
    elif isinstance(node, list):
        for value in node:
            _int_fact_key(value)


def _int_when_key(node):
    if isinstance(node, dict):
        when = node.get("when")
        if isinstance(when, dict) and "1" in when:
            when[1] = when.pop("1")
        for value in node.values():
            _int_when_key(value)
    elif isinstance(node, list):
        for value in node:
            _int_when_key(value)


def _tuple_trace(node):
    if isinstance(node, dict):
        trace = node.get("trace")
        if isinstance(trace, list):
            node["trace"] = tuple(trace)
        for value in node.values():
            _tuple_trace(value)
    elif isinstance(node, list):
        for value in node:
            _tuple_trace(value)


def _tamper_after_alpha(report, tamper):
    # Only the after bundle's first member is tampered: its legal twin in
    # the before bundle is parsed first, so a type-folding reuse identity
    # would let the impostor skip validation entirely.
    tamper(report["after"]["proofs"][0])
    return report


@pytest.mark.parametrize(
    "tamper", [_int_fact_key, _int_when_key, _tuple_trace]
)
def test_verify_rejects_equal_text_type_collision(tamper):
    report = _tamper_after_alpha(_diff(), tamper)
    with pytest.raises(ValueError):
        verify_checkpoint_chain_checkpoint_bundle_diff(report, _expected(report))


@pytest.mark.parametrize(
    "tamper", [_int_fact_key, _int_when_key, _tuple_trace]
)
def test_generate_rejects_equal_text_type_collision(tamper):
    after = _bundle_after()
    tamper(after["proofs"][0])
    with pytest.raises(ValueError):
        checkpoint_chain_checkpoint_bundle_diff(_bundle_before(), after)


@pytest.mark.parametrize(
    "tamper", [_int_fact_key, _int_when_key, _tuple_trace]
)
def test_illegal_first_occurrence_also_raises(tamper):
    # Order does not matter: an impostor that appears before its legal
    # twin is rejected by its own validation.
    report = _diff()
    tamper(report["before"]["proofs"][0])
    with pytest.raises(ValueError):
        verify_checkpoint_chain_checkpoint_bundle_diff(report, _expected(report))


def test_legal_twin_still_reuses_and_verifies():
    # Type-and-value-identical occurrences still share one recomputation:
    # the genuine diff verifies True and regenerates byte-identically.
    report = _diff()
    assert verify_checkpoint_chain_checkpoint_bundle_diff(
        report, _expected(report)
    ) is True
    again = checkpoint_chain_checkpoint_bundle_diff(_bundle_before(), _bundle_after())
    assert again == report


def test_http_untruthful_but_legal_is_200_valid_false():
    # A structurally legal report whose digest does not recompute is a
    # truthfulness failure, not a structural one: 200 with valid=false.
    report = _diff()
    report["digest"] = "0" * 64
    response = client.post(
        VERIFY_PATH, json={"report": report, "expected": _expected(report)}
    )
    assert response.status_code == 200
    assert response.json() == {"valid": False}

import copy

import pytest
from fastapi.testclient import TestClient

from regulation_policy_compiler.app import app
from regulation_policy_compiler.policy import (
    checkpoint_chain,
    checkpoint_chain_checkpoint,
    decision_matrix_attestation,
    decision_matrix_attestation_bundle,
    evolution_checkpoint,
    evolution_checkpoint_bundle,
    matrix_bundle_evolution,
    verify_checkpoint_chain_checkpoint,
)

client = TestClient(app)

START = "2021-01-01T00:00:00Z"
MID = "2021-02-01T00:00:00Z"
END = "2021-04-01T00:00:00Z"
AT1 = "2021-05-01T00:00:00Z"
AT2 = "2021-06-01T00:00:00Z"
AT3 = "2021-07-01T00:00:00Z"
RT1 = "2021-08-01T00:00:00Z"
RT2 = "2021-09-01T00:00:00Z"
RT3 = "2021-10-01T00:00:00Z"

VERIFY_PATH = (
    "/decision-matrix/attest/bundle/evolution/checkpoint/bundle/diff/"
    "chain/checkpoint/verify"
)


def _rule(**overrides):
    rule = {
        "id": "r1",
        "ver": 1,
        "source": "law",
        "priority": 0,
        "from": "2020-01-01T00:00:00Z",
        "to": None,
        "when": None,
        "result": "allow",
    }
    rule.update(overrides)
    return rule


def _changing_rules():
    return [
        _rule(id="a", priority=5, **{"from": START}, when={"x": True}, result="允许"),
        _rule(
            id="b",
            priority=1,
            **{"from": MID, "to": "2021-03-01T00:00:00Z"},
            result="deny",
        ),
    ]


def _report_a():
    return decision_matrix_attestation(
        START, END, [{"id": "c1", "facts": {"x": True}}], _changing_rules()
    )


def _report_b():
    return decision_matrix_attestation(
        START, END, [{"id": "c2", "facts": {}}], [_rule(result="z")]
    )


def _report_c():
    return decision_matrix_attestation(
        START, END, [{"id": "c3", "facts": {"y": False}}], [_rule(result="q")]
    )


def _matrix_bundle_one():
    return decision_matrix_attestation_bundle([{"id": "a", "report": _report_a()}])


def _matrix_bundle_two():
    return decision_matrix_attestation_bundle(
        [{"id": "a", "report": _report_a()}, {"id": "b", "report": _report_b()}]
    )


def _matrix_bundle_three():
    return decision_matrix_attestation_bundle(
        [
            {"id": "a", "report": _report_a()},
            {"id": "b", "report": _report_b()},
            {"id": "c", "report": _report_c()},
        ]
    )


def _checkpoint_proofs():
    evolution = matrix_bundle_evolution(
        [
            {"at": AT1, "bundle": _matrix_bundle_one()},
            {"at": AT2, "bundle": _matrix_bundle_two()},
            {"at": AT3, "bundle": _matrix_bundle_three()},
        ]
    )
    return {
        "head": evolution_checkpoint(evolution, AT1, AT1),
        "mid": evolution_checkpoint(evolution, AT2, AT2),
        "tail": evolution_checkpoint(evolution, AT3, AT3),
        "span": evolution_checkpoint(evolution, AT1, AT2),
    }


def _chain():
    proofs = _checkpoint_proofs()
    bundle_one = evolution_checkpoint_bundle(
        [{"id": "a", "proof": proofs["head"]}, {"id": "z", "proof": proofs["span"]}]

def _check_time(value: Any, field: str) -> str:
    if not isinstance(value, str) or _TIME_RE.fullmatch(value) is None:
        raise ValueError(f"{field} must be a UTC timestamp of the form YYYY-MM-DDTHH:MM:SSZ")
    try:
        datetime.strptime(value, "%Y-%m-%dT%H:%M:%SZ")
    except ValueError as exc:
        raise ValueError(f"{field} is not a valid calendar time: {value!r}") from exc
    return value


def _check_int(value: Any, field: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{field} must be an integer (bool is not accepted)")
    return value


def _check_non_empty_str(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value:
        raise ValueError(f"{field} must be a non-empty string")
    return value


def _check_fact_map(value: Any, field: str) -> dict[str, bool]:
    if not isinstance(value, dict):
        raise ValueError(f"{field} must be a dict[str, bool]")
    for key, item in value.items():
        if not isinstance(key, str) or not key:
            raise ValueError(f"{field} keys must be non-empty strings")
        if not isinstance(item, bool):
            raise ValueError(f"{field} values must be bool")
    return value


def _validate_rules(rules: Any) -> list[dict[str, Any]]:
    if not isinstance(rules, list):
        raise ValueError("rules must be a list of rule dicts")
    seen: set[tuple[str, str, int]] = set()
    for index, rule in enumerate(rules):
        field = f"rules[{index}]"
        if not isinstance(rule, dict) or set(rule) != _RULE_KEYS:
            raise ValueError(
                f"{field} must be a dict with exactly the keys "
                "id, ver, source, priority, from, to, when, result"
            )
        _check_non_empty_str(rule["id"], f"{field}.id")
        _check_non_empty_str(rule["result"], f"{field}.result")
        ver = _check_int(rule["ver"], f"{field}.ver")
        if ver < 1:
            raise ValueError(f"{field}.ver must be a positive integer")
        source = rule["source"]
        if source not in _SOURCES:
            raise ValueError(f"{field}.source must be 'law' or 'org'")
        _check_int(rule["priority"], f"{field}.priority")
        frm = _check_time(rule["from"], f"{field}.from")
        to = rule["to"]
        if to is not None:
            _check_time(to, f"{field}.to")
            if not frm < to:
                raise ValueError(f"{field} requires from < to")
        when = rule["when"]

def _vjs(value: Any) -> str:
    # JSON encoding for scalars (ids, kinds, hex64 strings, timestamps).
    return json.dumps(value, ensure_ascii=False)


# Sentinels tagging container and ambiguous-scalar kinds inside value keys.
# They are plain objects, so they can never equal a string, number, or other
# payload value; identity and hash are stable within the process, which is
# all a per-call engine registry needs.
_VKEY_BOOL = object()
_VKEY_FLOAT = object()
_VKEY_LIST = object()
_VKEY_TUPLE = object()
_VKEY_DICT = object()
_VKEY_OTHER = object()


def _vtype_key(value: Any) -> Any:
    """Type-faithful, sortable identity of a dict key (or other hashable).

    Every identity is a tag-first tuple, so identities of differently typed
    keys always order and compare without ``TypeError`` — an integer fact
    key never merges with or mis-sorts against the string with the same
    digits, and a tuple key never merges with anything else.  Used only for
    dict keys, which need a deterministic order; values use
    :func:`_vvalue_key`.
    """
    if isinstance(value, str):
        return ("s", value)
    if isinstance(value, bool):
        return ("b", value)
    if isinstance(value, int):
        return ("i", value)
    if isinstance(value, float):
        return ("f", value)
    if value is None:
        return ("n",)
    if isinstance(value, tuple):
        return ("t", tuple(_vtype_key(item) for item in value))
    return ("o", type(value).__qualname__, repr(value))


def _vvalue_key(value: Any) -> Any:
    """Type-faithful structural identity of a leaf credential value.

    The reuse registry must never merge values whose compact JSON text
    merely *looks* equal while their Python types differ: an integer fact
    or condition key and the string with the same digits, a tuple and the
    list with the same items, ``True`` and ``1``.  This key walks the
    value once and records the real type of every container and key, so
    only values equal in both type and value share an identity; anything
    else falls through to full validation, which rejects it.  Strings and
    ints map to themselves (they cannot collide with any other type's
    identity); containers, bools, floats, and exotica are tagged with
    sentinels that no payload value can equal.  Dict item order is
    normalized away by sorting on the (type-tagged) keys, and every legal
    credential contains only dicts, lists, strings, bools, ints, and
    nulls, for which the key is exact.  This is a structural walk, not a
    serialization: no text or byte form of the value is produced for
    keying.
    """
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        # Fast path: a string key is its own identity (no other key type
        # maps to a plain string, and plain strings sort unambiguously), so
        # the common all-string-key dict skips the per-key type tagging.
        items = []
        for key, item in value.items():
            if not isinstance(key, str):
                items = None
                break
            items.append((key, _vvalue_key(item)))
        if items is None:
            items = [
                (_vtype_key(key), _vvalue_key(item))
                for key, item in value.items()
            ]
        items.sort()
        return (_VKEY_DICT, tuple(items))
    if isinstance(value, list):
        return (_VKEY_LIST, tuple([_vvalue_key(item) for item in value]))
    if value is None:
        return None
    if isinstance(value, bool):
        return (_VKEY_BOOL, value)
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return (_VKEY_FLOAT, value)
    if isinstance(value, tuple):
        return (_VKEY_TUPLE, tuple([_vvalue_key(item) for item in value]))
    return (_VKEY_OTHER, type(value).__qualname__, repr(value))


class _CanonicalDict(dict):
    """A plain dict carrying the root of a canonical generator result.

    It behaves exactly like a plain ``dict`` in every respect — it *is* one:
    equality, ordering, iteration, JSON encoding, and ``isinstance`` checks
    are unchanged.  The only addition is a ``__deepcopy__`` that rebuilds
    the independent copy through the canonical compact JSON form, which is
    far cheaper than the generic recursive copier for the very large
    credential trees these functions return.  The copy is again a
    ``_CanonicalDict`` (so repeated copies stay on the fast path) over plain
    dicts and lists, so nothing beyond copying speed is observable, and the
    copy remains fully independent of the original at every level.
    """

    def __deepcopy__(self, memo: dict) -> Any:
        clone = _CanonicalDict(
            json.loads(json.dumps(self, ensure_ascii=False, separators=(",", ":")))
        )
        memo[id(self)] = clone
        return clone


def _emit(canonical_json: str) -> dict[str, Any]:
    """Materialize a canonical JSON document as an independent result tree."""
    return _CanonicalDict(json.loads(canonical_json))

class _VKey:
    """A hash-consed composite value key.

    Composite nodes (bundles, diffs, proofs) key their registries by tuples
    of scalar fields plus their children's keys.  Plain tuples re-hash the
    whole nested structure on every lookup; wrapping the tuple caches the
    hash once, so a repeat occurrence resolves in O(1).  Equality still
    compares the full underlying tuple, so distinct values can never merge.
    """

    __slots__ = ("parts", "_hash")

    def __init__(self, parts: Any) -> None:
        self.parts = parts
        self._hash = hash(parts)

    def __hash__(self) -> int:
        return self._hash

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, _VKey):
            return NotImplemented
        return self.parts == other.parts


class _VNode:
    __slots__ = (
        "key", "canonical", "json", "sem", "semkey", "dsem", "dsemkey",
        "truth", "complete",
        "root", "root_after", "members", "before_node", "after_node",
        "digest", "stage_parts",
    )

    def __init__(self) -> None:
        self.key: Any = None
        self.canonical: Any = None
        self.json: str = ""
        self.sem: Any = None
        self.semkey: Any = None
        self.dsem: Any = None
        self.dsemkey: Any = None
        self.truth: bool = False
        self.complete: bool = True
        self.root: str = ""
        self.root_after: str = ""
        self.members: list[Any] = []
        self.before_node: Any = None
        self.after_node: Any = None
        self.digest: str = ""
        self.stage_parts: list[str] = []


class _VEngine:
    def __init__(self) -> None:
        self.cred: dict[str, _VNode] = {}
        self.mbundle: dict[Any, _VNode] = {}
        self.mdiff: dict[Any, _VNode] = {}
        self.p0: dict[Any, _VNode] = {}
        self.b0: dict[Any, _VNode] = {}
        self.d0: dict[Any, _VNode] = {}
        self.p1: dict[Any, _VNode] = {}
        self.b1: dict[Any, _VNode] = {}
        self.d1: dict[Any, _VNode] = {}
        self.p2: dict[Any, _VNode] = {}
        self.b2: dict[Any, _VNode] = {}
        self.d2: dict[Any, _VNode] = {}
        self.p3: dict[Any, _VNode] = {}
        self.b3: dict[Any, _VNode] = {}
        self.d3: dict[Any, _VNode] = {}
        # Generated diffs are fully determined by the two side nodes and the
        # derived change entries; memoizing on those avoids rebuilding the
        # whole five-item payload (and its SHA-256) for a repeated pair.
        self.gen: dict[Any, _VNode] = {}
        # Format checks are pure in the input string, so a validated
        # timestamp or hex64 summary is remembered for the life of the
        # engine (one top-level call) instead of being re-checked at every
        # occurrence.
        self.times: dict[str, str] = {}
        self.hexes: dict[str, str] = {}

    def _time(self, value: Any, field: str) -> str:
        if isinstance(value, str):
            cached = self.times.get(value)
            if cached is not None:
                return cached
        checked = _check_time(value, field)
        self.times[checked] = checked
        return checked

    def _hex64(self, value: Any, field: str) -> str:
        if isinstance(value, str):
            cached = self.hexes.get(value)
            if cached is not None:
                return cached
        checked = _check_hex64(value, field)
        self.hexes[checked] = checked
        return checked

    # ------------------------------------------------------------ leaf cred
    def credential(self, value: Any, field: str) -> _VNode:
        if not isinstance(value, dict):
            raise ValueError(f"{field} must be a credential dict")
        # The reuse identity is a type-faithful structural key, not JSON
        # text: it records the real type of every container and key, so a
        # value that merely serializes like an already-seen credential (an
        # integer fact or condition key where the same digits were verified
        # as a string, a tuple where a list is required) never reuses that
        # credential's verified node.  Such a value falls through to full
        # validation, which reports the structural/type violation as
        # ValueError (never a TypeError), so it is never cached; only a
        # genuine type-and-value match resolves to the cached node.
        key = _VKey(("cred", _vvalue_key(value)))
        node = self.cred.get(key)
        if node is not None:
            return node
        content, declared, recomputed, chain_ok, chain_root = (
            _check_verified_matrix_attestation(value, field)
        )
        # The normalized content is a fresh canonical-order dict owned by
        # this call; appending the declared digest yields the canonical
        # report directly, so no defensive copy is needed before encoding.
        sem = _matrix_credential_semantics(content)
        content["digest"] = declared
        cjson = json.dumps(content, ensure_ascii=False, separators=(",", ":"))
        node = _VNode()
        node.key = key
        node.json = cjson
        node.sem = sem
        node.semkey = (
            "cred",
            json.dumps(node.sem, ensure_ascii=False, sort_keys=True,
                       separators=(",", ":")),
        )
        node.truth = bool(
            chain_ok
            and content["policy"]["root"] == chain_root
            and declared == recomputed
        )
        self.cred[key] = node
        return node

    # ------------------------------------------------------- shared members
    def _bundle_members(self, value, field, plural, singular, parse_child):
        if not isinstance(value, dict) or set(value) != {"root", plural}:
            raise ValueError(
                f"{field} must be a dict with exactly the keys root, {plural}"
            )
        root = self._hex64(value["root"], f"{field}.root")
        raw = value[plural]
        if not isinstance(raw, list) or not raw:
            raise ValueError(f"{field}.{plural} must be a non-empty list")
        members: list[tuple[str, _VNode, str, str]] = []
        seen: set[str] = set()
        previous_id: str | None = None
        for index, member in enumerate(raw):
            mf = f"{field}.{plural}[{index}]"
            if not isinstance(member, dict) or set(member) != {
                "id", singular, "previous", "digest"
            }:
                raise ValueError(
                    f"{mf} must be a dict with exactly the keys "
                    f"id, {singular}, previous, digest"
                )
            item_id = _check_non_empty_str(member["id"], f"{mf}.id")
            if item_id in seen:
                raise ValueError(
                    f"{field}.{plural} contains a duplicate id: {item_id!r}"
                )
            if previous_id is not None and item_id <= previous_id:
                raise ValueError(
                    f"{field}.{plural} must be ordered by id in ascending "
                    "Unicode code point order"
                )
            child = parse_child(member[singular], f"{mf}.{singular}")
            prev = self._hex64(member["previous"], f"{mf}.previous")
            dig = self._hex64(member["digest"], f"{mf}.digest")
            members.append((item_id, child, prev, dig))
